VIEWS.cp=()=>isPH()?cpParent():cpLead();
ACT.cpkid=v=>{S.cp.kid=v};ACT.cptab=v=>{S.cp.tab=v};ACT.cpm=v=>{S.cp.m=sm(S.cp.m,+v)};
function upcoming(k,n){const out=[];for(let i=0;i<10&&out.length<n;i++){const d=addD(TODAY,i);if(!isW(d))continue;sched(k,d.slice(0,7)).filter(x=>x.d===d).forEach(x=>out.push(x))}return out}
function cpParent(){const ks=myKids();
 if(!ks.length)return head('Cổng phụ huynh','')+'<div class="card"><p class="empty">Tài khoản này chưa gắn với bé nào. Hãy liên hệ Trung tâm.</p></div>';
 const c=S.cp=Object.assign({tab:'tq',kid:ks[0].id,m:WD.slice(0,7)},S.cp);if(!ks.some(k=>k.id===c.kid))c.kid=ks[0].id;const k=kidBy(c.kid);
 return head('Xin chào, '+esc(given(U.name)),'Thông tin học tập của bé trong '+esc(DB.cfg.name))+(ks.length>1?tabsH(ks.map(x=>[x.id,given(x.n)]),c.kid,'cpkid'):'')
 +`<div class="card" style="display:flex;gap:14px;align-items:center;flex-wrap:wrap"><span class="av" style="width:52px;height:52px;font-size:22px" aria-hidden="true">${esc(given(k.n).split(' ').pop().charAt(0))}</span><div><h2 style="margin:0">${esc(k.n)}</h2><p class="mu sm">${age(k.dob)} · ${esc(progOf(k))} · Giáo viên ${esc(mainGV(k))}</p></div></div>`
 +tabsH([['tq','Tổng quan'],['ch','Chuyên cần và học phí'],['bc','Báo cáo'],['vd','Video và tài liệu']],c.tab,'cptab')+(c.tab==='tq'?cpHome(k):c.tab==='ch'?cpMonth(k):c.tab==='bc'?cpReports(k):vidList(k.id)+'<h2 style="margin-top:18px">Tài liệu</h2>'+docList(k.id))}
function cpHome(k){const up=upcoming(k,6),last=DB.sess.filter(s=>s.k===k.id&&s.note).sort((a,b)=>a.date<b.date?1:-1)[0],b=balance(k.id);
 return`<div class="grid">${kpi('Học phí',b>0?fmt(b):b<0?fmt(-b):'Đủ',b>0?'còn phải đóng':b<0?'dư có, trừ vào tháng sau':'đã đóng đủ',b>0?'er':'ok')}${kpi('Thông báo mới',unread(),'chưa đọc')}${kpi('Báo cáo đã nhận',DB.rp.filter(r=>r.hs===k.id&&r.s==='gui').length,'từ giáo viên')}</div>`
 +`<div class="two"><div class="card"><h2>Lịch học sắp tới</h2>${up.length?up.map(x=>`<div class="rw"><span><b>${DAYS[dow(x.d)]} ${vdm(x.d)}</b> · ${x.kind==='bt'?'Bán trú '+esc((grBy(x.sid)||{}).n||''):x.kind==='bu'?'Học bù '+slotLb(x.slot):'Can thiệp 1-1 '+slotLb(x.slot)}</span></div>`).join(''):'<p class="empty">Chưa có lịch trong 10 ngày tới.</p>'}<div class="acts" style="margin-top:10px"><button class="btn s" data-a="nav" data-v="hb">Đăng ký học bù</button></div></div>
 <div class="card"><h2>Nhận xét buổi gần nhất</h2>${last?`<p class="mu sm">${vd(last.date)}</p><p>${esc(last.note)}</p>`:'<p class="empty">Chưa có nhận xét.</p>'}</div></div>`
 +`<div class="card"><h2>Tiến bộ theo mục tiêu</h2>${progH(k.id)}</div>`}
function cpMonth(k){const c=S.cp,m=c.m,r=settle(k,m),ds=mDates(m),lead=(dow(ds[0])+6)%7,billedM=billed(k.id,m),nm=sm(m,1);
 const cells=Array.from({length:lead},()=>'<div style="border:0"></div>').concat(ds.map(d=>`<div class="${dow(d)===0?'sun':''}"><b>${pd(d).getDate()}</b><div>${(r.cells[d]||[]).map(x=>`<i class="sc sc-${symCls(x)}">${x}</i>`).join('')}</div></div>`)).join('');
 return`<div class="card"><div class="top"><h2>${mLabel(m)}</h2><div class="acts"><button class="btn s" data-a="cpm" data-v="-1">Tháng trước</button><button class="btn s" data-a="cpm" data-v="1" ${m>=CM?'disabled':''}>Tháng sau</button></div></div>
 <div class="legend">${Object.entries(SYM).map(([x,l])=>`<span><i class="sc sc-${symCls(x)}">${x}</i> ${l}</span>`).join('')}</div>
 <div class="cal" role="img" aria-label="Lịch điểm danh ${mLabel(m)}">${['T2','T3','T4','T5','T6','T7','CN'].map(x=>`<span class="sm mu" style="text-align:center">${x}</span>`).join('')}${cells}</div>
 <div class="grid" style="margin-top:14px">${kpi('Có mặt',r.cm+r.bu,'trong tháng','ok')}${kpi('Nghỉ',r.p+r.kp+r.tt+r.bv,'P '+r.p+', KP '+r.kp+', TT/GV '+r.tt+', viện '+r.bv)}${kpi('Học phí tháng',fmt(billedM),'')}${kpi('Hoàn trừ tháng sau',fmt(r.refund),'phí mất '+fmt(r.lost),'ok')}</div></div>`
 +`<div class="card"><h2>Các buổi nghỉ và cách tính</h2>`+tbl(['Ngày','Loại','Trạng thái','Cách tính','>Mất (₫)','>Hoàn (₫)'],r.rows.sort((a,b)=>a.d<b.d?-1:1).map(x=>`<tr><td class="nw">${DAYS[dow(x.d)]} ${vdm(x.d)}</td><td>${x.kind==='11'?'1-1':'Bán trú'}</td><td>${tg(AC[x.code],x.code==='kp'?'er':x.code==='p'?'wa':'gy')}</td><td>${esc(x.note)}</td><td class="r nw">${fnum(x.ls)}</td><td class="r nw">${fnum(x.rf)}</td></tr>`).join(''),'Bé không có buổi nghỉ nào trong tháng.')
 +`<p class="sm mu" style="margin-top:8px">Khoản hoàn được trừ vào học phí ${mLabel(nm)}. Nếu bé nghỉ, vui lòng báo trong nhóm chung trước 7g sáng hôm đó (ca chiều và tối: trước 12g); xem quy định đầy đủ bên dưới.</p><details style="margin-top:8px"><summary class="sm" style="cursor:pointer"><b>Quy định học phí và hoàn phí</b></summary>${k.m11||wk11(k.id)?policyH('m11'):''}${k.bt?policyH('bt'):''}</details></div>`}
function cpReports(k){const rs=DB.rp.filter(r=>r.hs===k.id&&r.s==='gui').sort((a,b)=>a.per<b.per?1:-1);
 return rs.length?rs.map((r,i)=>`<div class="card"><details ${i===0?'open':''}><summary style="cursor:pointer"><b>Báo cáo ${mLabel(r.per)}</b> · giáo viên ${esc(given(sn(r.au)))}</summary><div style="margin-top:10px">${rpDoc(r)}<div class="acts" style="margin-top:12px"><button class="btn s" data-a="bcpdf" data-v="${r.id}">Tải PDF</button></div></div></details></div>`).join(''):'<div class="card"><p class="empty">Chưa có báo cáo nào được gửi. Khi giáo viên hoàn thành, báo cáo sẽ hiện ở đây.</p></div>'}
/* --- góc nhìn quản lý --- */
function cpLead(){const by={};DB.kids.forEach(k=>{(by[k.pe]=by[k.pe]||{pe:k.pe,pn:k.pn,pp:k.pp,ks:[]}).ks.push(k)});const ps=Object.values(by),sent=DB.rp.filter(r=>r.s==='gui'),wait=DB.rp.filter(r=>r.s==='duyet');
 const pgd=pg('cpl',ps,12);
 return head('Cổng phụ huynh','Theo dõi tài khoản phụ huynh và nội dung đã gửi')
 +`<div class="grid">${kpi('Tài khoản phụ huynh',ps.length,DB.kids.length+' bé')}${kpi('Báo cáo đã gửi',sent.length,'phụ huynh xem được','ok')}${kpi('Chờ gửi',wait.length,'đã duyệt, chưa gửi',wait.length?'er':'')}${kpi('Video chia sẻ',SH.videos.filter(v=>v.sh).length,'cho phụ huynh')}</div>`
 +(wait.length?`<div class="card"><h2>Báo cáo đã duyệt, chờ gửi</h2>`+wait.map(r=>`<div class="rw"><span><b>${esc(kn(r.hs))}</b> · ${mLabel(r.per)}</span><button class="btn s y" data-a="bcsend" data-v="${r.id}">Gửi phụ huynh</button></div>`).join('')+`</div>`:'')
 +`<div class="card"><h2>Tài khoản phụ huynh</h2>`+tbl(['Phụ huynh','Email đăng nhập','Các bé','Báo cáo đã nhận','Thông báo chưa đọc',''],pgd.rows.map(p=>{const nr=DB.nt.filter(n=>n.aud==='ph'&&(n.tg==='all'||p.ks.some(k=>k.id===n.tg||k.gr===n.tg))&&!DB.rd[n.id+'|ph|'+p.pe]).length;
  return`<tr><td><b>${esc(p.pn)}</b><br><span class="sm mu">${esc(p.pp)}</span></td><td>${esc(p.pe)}</td><td>${esc(p.ks.map(k=>k.n).join(', '))}</td><td>${sent.filter(r=>p.ks.some(k=>k.id===r.hs)).length}</td><td>${nr}</td><td><button class="btn s" data-a="viewas" data-v="${esc(p.pe)}">Xem như phụ huynh</button></td></tr>`}).join(''))+pgd.html+`<p class="sm mu" style="margin-top:8px">“Xem như phụ huynh” chuyển bạn sang giao diện của tài khoản đó để kiểm tra. Đổi lại vai trò bằng ô “Xem thử vai trò” ở đầu trang.</p></div>`}
