ACT.tbnew=()=>{S.modal={t:'tbn',aud:isLead()?'ph':'ph'}};
CHG.tba=v=>{S.modal.aud=v};
MODALS.tbn=()=>{const m=S.modal,gs=isGV()?myGroups():DB.groups,ks=isGV()?myKids().filter(k=>k.st==='dang'):[];
 const tgOpts=m.aud==='nb'?[['all','Toàn bộ nhân viên']]:(isLead()?[['all','Mọi phụ huynh']]:[]).concat(gs.map(g=>[g.id,'Phụ huynh '+g.n])).concat(isLead()?DB.kids.filter(k=>k.st==='dang').map(k=>['k:'+k.id,'Phụ huynh bé '+k.n]):ks.map(k=>['k:'+k.id,'Phụ huynh bé '+k.n]));
 return mdl('Soạn thông báo',`<form id="tbf" class="f"><div class="f2">${isLead()?`<div><label for="tb-a">Gửi cho</label><select id="tb-a" data-c="tba">${opts([['ph','Phụ huynh'],['nb','Nhân viên']],m.aud)}</select></div>`:''}<div><label for="tb-g">Đối tượng cụ thể</label><select id="tb-g" name="tg">${opts(tgOpts,'')}</select></div></div><div><label for="tb-t">Tiêu đề</label><input id="tb-t" name="t" required></div><div><label for="tb-b">Nội dung</label><textarea id="tb-b" name="b" rows="5" required></textarea></div>${isLead()?'<label class="chk"><input type="checkbox" name="pin"> Ghim lên đầu</label>':''}<div class="acts" style="justify-content:flex-end"><button class="btn" type="button" data-a="mx">Hủy</button><button class="btn p" type="submit">Gửi thông báo</button></div></form>`)};
FORM.tbf=f=>{const e=f.elements,g=e.tg.value;if(!g)return false;
 DB.nt.push({id:'n'+uid(),aud:S.modal.aud,tg:g.startsWith('k:')?g.slice(2):g,t:e.t.value.trim(),b:e.b.value.trim(),by:U.id,at:TODAY,pin:!!(e.pin&&e.pin.checked)});S.modal=null;toast('Đã gửi thông báo')};
