CHG.tkm=v=>{S.tk.m=v};
function attStats(m){const lich={};DB.lich.forEach(l=>{lich[l.id]=l});const by={};
 for(const key in DB.att){if(!key.startsWith(m))continue;const sid=key.split('|')[1],c=DB.att[key];let gv;if(sid[0]==='G'){const g=grBy(sid);gv=g&&g.gv}else{const l=lich[sid];gv=l&&l.gv}
  if(!gv)continue;const o=by[gv]=by[gv]||{t:0,cm:0,p:0,kp:0,tt:0,bv:0};o.t++;o[c]++}
 return by}
function tkData(m){const act=DB.kids.filter(k=>k.st==='dang'),as=attStats(m),tot=Object.values(as).reduce((a,o)=>({t:a.t+o.t,cm:a.cm+o.cm}),{t:0,cm:0}),fs=feeStats(m);
 const prog=[['Chỉ can thiệp 1-1',k=>wk11(k.id)&&!k.bt],['Cả 1-1 và bán trú',k=>wk11(k.id)&&k.bt],['Chỉ bán trú',k=>!wk11(k.id)&&k.bt]].map(([l,f])=>{const ks=act.filter(f);return{l,n:ks.length,due:ks.reduce((s,k)=>s+billed(k.id,m),0),paid:ks.reduce((s,k)=>s+paidM(k.id,m),0)}});
 const tr=DB.staff.filter(s=>s.role==='gv'&&s.st==='dang').map(s=>({s,o:as[s.id]||{t:0,cm:0,p:0,kp:0,tt:0,bv:0},ks:act.filter(k=>k.gv===s.id).length}));
 const refund=DB.lg.filter(e=>e.kind==='hoan'&&e.m===m).reduce((s,e)=>s+e.amt,0);
 return{act,tot,fs,prog,tr,refund,rate:tot.t?Math.round(tot.cm*100/tot.t):0}}
VIEWS.tk=()=>{const t=S.tk=Object.assign({m:sm(WD.slice(0,7),0)},S.tk),m=t.m,d=tkData(m);
 return head('Thống kê','Số liệu tổng hợp theo tháng, xuất Excel hoặc PDF','<button class="btn s" data-a="tkxl">Xuất Excel</button><button class="btn s" data-a="tkpdf">Xuất PDF</button>')
 +`<div class="card"><div class="f2"><div><label for="tkm">Tháng</label><select id="tkm" data-c="tkm">${opts([sm(CM,-2),sm(CM,-1),CM].map(x=>[x,mLabel(x)]),m)}</select></div></div></div>`
 +`<div class="grid">${kpi('Trẻ đang học',d.act.length,DB.kids.length+' hồ sơ')}${kpi('Chuyên cần',d.rate+'%',d.tot.t+' lượt đã điểm danh',d.rate>=85?'ok':'er')}${kpi('Đã thu',fmt(d.fs.paid),'phải thu '+fmt(d.fs.due))}${kpi('Công nợ',fmt(totalDebt()),debtors().length+' gia đình',totalDebt()?'er':'ok')}${kpi('Hoàn phí nghỉ',fmt(d.refund),'trừ vào học phí '+mLabel(m))}</div>`
 +`<div class="two"><div class="card"><h2>Học phí theo chương trình</h2>`+tbl(['Chương trình','>Số trẻ','>Phải thu','>Đã thu'],d.prog.map(p=>`<tr><td>${p.l}</td><td class="r">${p.n}</td><td class="r nw">${fnum(p.due)}</td><td class="r nw">${fnum(p.paid)}</td></tr>`).join(''))+`</div>
 <div class="card"><h2>Chuyên cần theo giáo viên</h2>`+tbl(['Giáo viên','>Trẻ 1-1','>Lượt','>Có mặt','>P','>KP','>TT/GV'],d.tr.map(({s,o,ks})=>`<tr><td>${esc(given(s.n))}</td><td class="r">${ks}</td><td class="r">${o.t}</td><td class="r">${o.t?Math.round(o.cm*100/o.t):0}%</td><td class="r">${o.p}</td><td class="r">${o.kp}</td><td class="r">${o.tt}</td></tr>`).join(''))+`</div></div>`
 +`<div class="card"><h2>Nhân sự: công và đi muộn</h2>`+tbl(['Nhân viên','Chức vụ','>Công','>Đi muộn','>Nghỉ phép','>Vắng'],DB.staff.filter(s=>s.st==='dang').map(s=>{const p=payroll(s,m);return`<tr><td>${esc(s.n)}</td><td>${esc(s.pos)}</td><td class="r">${p.cong}</td><td class="r">${p.late}</td><td class="r">${p.leave}</td><td class="r">${p.abs}</td></tr>`}).join(''))+`</div>`};
ACT.tkxl=()=>{const m=S.tk.m,d=tkData(m);
 exportXLSX('thong-ke-'+m+'.xlsx',[{n:'Tổng quan',rows:[['Chỉ số','Giá trị'],['Tháng',mLabel(m)],['Trẻ đang học',d.act.length],['Chuyên cần (%)',d.rate],['Phải thu',d.fs.due],['Đã thu',d.fs.paid],['Công nợ hiện tại',totalDebt()],['Hoàn phí nghỉ',d.refund]]},
  {n:'Học sinh',rows:[['Mã','Họ tên','Tuổi','Nhu cầu','Chương trình','Giáo viên','Phụ huynh','Điện thoại','Trạng thái']].concat(DB.kids.map(k=>[k.id,k.n,age(k.dob),k.nd,progOf(k),mainGV(k),k.pn,k.pp,KST[k.st]]))},
  {n:'Chuyên cần giáo viên',rows:[['Giáo viên','Trẻ 1-1','Lượt','Có mặt','Nghỉ P','Nghỉ KP','TT/GV nghỉ']].concat(d.tr.map(({s,o,ks})=>[s.n,ks,o.t,o.cm,o.p,o.kp,o.tt]))},
  {n:'Học phí',rows:[['Mã','Họ tên','Học phí '+m,'Đã thu','Công nợ hiện tại']].concat(d.act.map(k=>[k.id,k.n,billed(k.id,m),paidM(k.id,m),balance(k.id)]))},
  {n:'Nhân sự',rows:[['Mã','Họ tên','Chức vụ','Công','Đi muộn','Nghỉ phép','Vắng']].concat(DB.staff.filter(s=>s.st==='dang').map(s=>{const p=payroll(s,m);return[s.id,s.n,s.pos,p.cong,p.late,p.leave,p.abs]}))}])};
ACT.tkpdf=()=>{const m=S.tk.m,d=tkData(m),r=(a,b)=>`<tr><td>${a}</td><td align="right">${b}</td></tr>`;
 exportPDF('thong-ke-'+m+'.pdf',`<h2 style="margin:0 0 8px;font:700 17px 'Baloo 2','Be Vietnam Pro',sans-serif">THỐNG KÊ ${mLabel(m).toUpperCase()}</h2><table><tbody>${r('Trẻ đang học',d.act.length)}${r('Chuyên cần',d.rate+'% ('+d.tot.t+' lượt)')}${r('Học phí phải thu',fmt(d.fs.due))}${r('Đã thu',fmt(d.fs.paid))}${r('Công nợ hiện tại',fmt(totalDebt()))}${r('Hoàn phí nghỉ',fmt(d.refund))}</tbody></table><h3 style="margin:14px 0 6px">Học phí theo chương trình</h3><table><thead><tr><th>Chương trình</th><th>Số trẻ</th><th>Phải thu</th><th>Đã thu</th></tr></thead><tbody>${d.prog.map(p=>`<tr><td>${p.l}</td><td>${p.n}</td><td align="right">${fnum(p.due)}</td><td align="right">${fnum(p.paid)}</td></tr>`).join('')}</tbody></table><h3 style="margin:14px 0 6px">Chuyên cần theo giáo viên</h3><table><thead><tr><th>Giáo viên</th><th>Lượt</th><th>Có mặt</th><th>P</th><th>KP</th><th>TT/GV</th></tr></thead><tbody>${d.tr.map(({s,o})=>`<tr><td>${esc(s.n)}</td><td>${o.t}</td><td>${o.t?Math.round(o.cm*100/o.t):0}%</td><td>${o.p}</td><td>${o.kp}</td><td>${o.tt}</td></tr>`).join('')}</tbody></table>`)};
